'use strict';
function main(){
var wh=33.5,w=9.0,T=848.9;
var derate=T<0?0.6:1;
var h=wh*derate/w;
return {battery_wh:wh, heater_w:w, ambient_c:T, cold_derate:derate, runtime_hours:Math.round(h*10)/10};
}
try{var out=main();console.log(JSON.stringify(out));}catch(e){console.log(JSON.stringify({error:String(e&&e.message||e)}));process.exitCode=1;}

